std::vector<Point2d> intersectionPoints;
for (unsigned int i = 0; i < segments.size(); i++) {
    for (unsigned int j = i + 1; j < segments.size(); j++) {
        Point2d p1From = segments[i].p1();
        Point2d p1To = segments[i].p2();
        Point2d p2From = segments[j].p1();
        Point2d p2To = segments[j].p2();
        double eps = 0.001;
        if ((cg3::epsilonEqual(p1From.x(), p2From.x(), eps) && cg3::epsilonEqual(p1From.y(), p2From.y(), eps)) ||
            (cg3::epsilonEqual(p1To.x(), p2To.x(), eps) && cg3::epsilonEqual(p1To.y(), p2To.y(), eps)) ||
            (cg3::epsilonEqual(p1From.x(), p2To.x(), eps) && cg3::epsilonEqual(p1From.y(), p2To.y(), eps)) ||
            (cg3::epsilonEqual(p2From.x(), p1To.x(), eps) && cg3::epsilonEqual(p2From.y(), p1To.y(), eps))) {
            continue;
        }
        CK_Segment_2 cgalSeg1(CK_Point_2(p1From.x(), p1From.y()), CK_Point_2(p1To.x(), p1To.y()));
        CK_Segment_2 cgalSeg2(CK_Point_2(p2From.x(), p2From.y()), CK_Point_2(p2To.x(), p2To.y()));
        if (CGAL::do_intersect(cgalSeg1, cgalSeg2)) {
            auto intersection = CGAL::intersection(cgalSeg1, cgalSeg2);
            if (const CK_Point_2* point = boost::get<CK_Point_2>(&*intersection)) {
                intersectionPoints.push_back(Point2d(point->x(), point->y()));
            }
        }
    }
}
return intersectionPoints;

